declare(strict_types=1);

namespace MM\ItalianFiscalFields\Tests;

use Mage;
use PHPUnit\Framework\TestCase;

/**
 * Verifies that Maho bootstraps from this package's own vendor, the way
 * maho's own install tests do, and that the module classes are autoloadable
 * through the psr-0 prefix generated by the maho composer plugin.
 */
final class BootstrapTest extends TestCase
{
    protected function setUp(): void
    {
        parent::setUp();

        Mage::setRoot(dirname(__DIR__) . '/vendor/mahocommerce/maho');
        Mage::app();
    }

    protected function tearDown(): void
    {
        Mage::reset();
        restore_error_handler();
        restore_exception_handler();

        parent::tearDown();
    }

    public function testMahoBootstrapsFromThePackageVendor(): void
    {
        self::assertInstanceOf(\Mage_Core_Model_App::class, Mage::app());
    }

    public function testModuleClassesAreAutoloadable(): void
    {
        self::assertTrue(class_exists(\MM_ItalianFiscalFields_Block_Config_Abstract::class));
        self::assertTrue(class_exists(\MM_ItalianFiscalFields_Block_Config_Customer_Address_Config::class));
        self::assertTrue(class_exists(\MM_ItalianFiscalFields_Block_Config_Checkout_Onepage_Config::class));
        self::assertTrue(class_exists(\MM_ItalianFiscalFields_Helper_Data::class));
        self::assertTrue(class_exists(\MM_ItalianFiscalFields_Model_Source_CustomerType::class));
    }
}
